mkdir -p app/Services && cat > app/Models/Attachment.ts <<'EOF'
import { defineModel } from '@guren/core'
import { attachments } from '../../db/schema.js'

export type AttachmentRecord = typeof attachments.$inferSelect

// Rows are written only by CoverStorage, from server-side data.
export class Attachment extends defineModel(attachments, {
  fillable: [],
}) {}
EOF
cat > app/Services/CoverStorage.ts <<'EOF'
import { mkdir, rm, unlink } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { join } from 'node:path'
import { ValidationException } from '@guren/core'
import { Attachment, type AttachmentRecord } from '../Models/Attachment.js'

export const COVER_MAX_BYTES = 2 * 1024 * 1024
export const COVER_TYPES = ['image/png', 'image/jpeg'] as const
export const COVER_ERROR = 'Cover must be a PNG or JPEG image of at most 2 MB.'

const STORAGE_DIR = fileURLToPath(new URL('../../storage/covers/', import.meta.url))

function sniff(bytes: Uint8Array): 'image/png' | 'image/jpeg' | null {
  const png = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]
  if (png.every((byte, i) => bytes[i] === byte)) return 'image/png'
  if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'image/jpeg'
  return null
}

/** Checks the upload's content, not just its declared type. Throws the same 422 a bad title does. */
export async function readCover(file: File): Promise<{ bytes: Uint8Array; contentType: string }> {
  const bytes = new Uint8Array(await file.arrayBuffer())
  const contentType = sniff(bytes)
  if (bytes.length > COVER_MAX_BYTES || contentType === null) {
    throw new ValidationException({ cover: [COVER_ERROR] })
  }
  return { bytes, contentType }
}

export async function findCover(postId: number): Promise<AttachmentRecord | null> {
  return Attachment.first({ postId })
}

export async function storeCover(postId: number, file: File, cover: { bytes: Uint8Array; contentType: string }) {
  await mkdir(STORAGE_DIR, { recursive: true })
  const path = `${crypto.randomUUID()}.${cover.contentType === 'image/png' ? 'png' : 'jpg'}`
  await Bun.write(join(STORAGE_DIR, path), cover.bytes)
  try {
    return await Attachment.forceCreate({
      postId,
      path,
      filename: file.name || path,
      contentType: cover.contentType,
      size: cover.bytes.length,
    })
  } catch (error) {
    await unlink(join(STORAGE_DIR, path)).catch(() => {})
    throw error
  }
}

/** Deletes the row and the file. */
export async function removeCover(attachment: AttachmentRecord): Promise<void> {
  await Attachment.delete({ id: attachment.id })
  await rm(join(STORAGE_DIR, attachment.path), { force: true })
}

export function coverFile(attachment: AttachmentRecord): Bun.BunFile {
  return Bun.file(join(STORAGE_DIR, attachment.path))
}

export function coverUrl(attachment: AttachmentRecord | null | undefined): string | null {
  return attachment ? `/attachments/${attachment.id}` : null
}
EOF
grep -n "ValidationException" node_modules/@guren/core/dist/index.js | head -2

result:
Posts now support cover images on create and edit. `bun run typecheck` and `bun test` both pass, including a new `tests/PostCover.test.ts`. I did not boot the app or try the forms in a browser.

The new test covers:
- upload and serving the bytes back unchanged;
- a refused GIF on edit keeping the old cover;
- replacing a cover deletes the old file, and the old URL returns 404;
- editing without a file leaves the cover alone, and `removeCover=1` removes it;
- an oversized upload creating no post;
- deleting a post deletes its cover file and row.

- **Storage:** `attachments` is a new table with a migration, one row per cover. Files are written to `storage/covers/` under a random name. I added `storage/` to `.gitignore`.
- **Serving:** `GET /attachments/:id` streams the file back with its stored content type. A replaced, removed or deleted cover gets a new or missing row, so its old URL returns 404.
- **Validation:** the cover's actual bytes are checked, not the declared content type, so a GIF labelled `image/png` is refused. The limit is 2 MB. A refused cover fails with the same 422 `ValidationException` as a bad title, with the message on the `cover` field, and nothing is saved.
- **Page data:** the posts list, post page and search results all include `coverUrl: string | null`. The edit page also gets `coverUrl`, so the form can show the current cover.
- **Forms:** the new and edit pages have a file input, and edit adds a "Remove cover" checkbox that sends `removeCover=1`. The index and show pages render the cover when there is one.
- **Codegen:** I ran `bun run codegen`, which updated the files under `.guren/`.

The controller changes are in `app/Http/Controllers/PostController.ts`, and the storage logic is in the new `app/Services/CoverStorage.ts`.
